"""Chat API route and same-origin image-aware browser interface."""

import httpx
from fastapi import APIRouter, HTTPException

from .config import Settings
from .knowledge import KnowledgeBase
from .schemas import ChatRequest, ChatResponse
from .service import ChatError, ChatService


def create_chat_router(settings: Settings | None = None, knowledge: KnowledgeBase | None = None) -> APIRouter:
    settings = settings or Settings.from_env()
    knowledge = knowledge if knowledge is not None else KnowledgeBase.load(settings.data_path)
    router = APIRouter(tags=["Chatbot"])

    @router.post("/chat", response_model=ChatResponse)
    async def chat(request: ChatRequest) -> ChatResponse:
        async with httpx.AsyncClient(timeout=30.0, follow_redirects=False) as client:
            try:
                return await ChatService(settings, knowledge, client).reply(request)
            except ChatError as exc:
                raise HTTPException(status_code=exc.status, detail=exc.message) from exc

    return router


def chat_demo_html() -> str:
    return """<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hieroglyph Chatbot</title><style>body{font:16px system-ui;background:#faf7ef;color:#28251e;margin:0;padding:24px}main{max-width:780px;margin:auto}#chat{min-height:220px;background:white;border:1px solid #d8ceb8;border-radius:12px;padding:18px;margin:20px 0}.turn{white-space:pre-wrap;overflow-wrap:anywhere;margin:12px 0;padding:12px;border-radius:8px;background:#f4f0e5}.user{background:#e9f1f1}.image{max-width:100%;border-radius:8px;margin-top:8px}.result{border-left:4px solid #315553;background:#edf5f3}.symbols{margin:8px 0;padding-left:20px}label{display:block;margin:12px 0 5px}input,textarea,button{font:inherit;box-sizing:border-box;border:1px solid #b7ab90;border-radius:7px;padding:10px}input,textarea{width:100%}textarea{height:90px}button{background:#315553;color:white;cursor:pointer;margin-top:12px;margin-right:6px}button:disabled{opacity:.5}#status{min-height:24px;color:#8a3028}.note{font-size:14px;color:#68604f}.audio{background:#704c2a}</style><main><h1>Hieroglyph Chatbot</h1><p>Ask about a symbol, Gardiner code, or Ancient Egyptian writing. اسأل بالعربي أو بالإنجليزي.</p><p class=note>Upload a JPG, PNG, or WebP image up to 10 MB. Symbol numbers are only labels for this screen, not inscription reading order.</p><div id=chat aria-live=polite></div><form id=form><label for=image>Upload a hieroglyph image</label><input id=image type=file accept="image/jpeg,image/png,image/webp"><label for=codes>Glyph codes (optional, separated by commas)</label><input id=codes placeholder="A1, S34" maxlength=250><label for=message>Your question</label><textarea id=message dir=auto placeholder="What does S34 mean?" maxlength=2000 required></textarea><button id=send>Send</button><button id=clear type=button>New conversation</button></form><p id=status role=status></p></main><script>const history=[],chat=document.getElementById('chat'),status=document.getElementById('status'),send=document.getElementById('send'),clear=document.getElementById('clear'),imageInput=document.getElementById('image');let detectedCodes=[],imageContext='';function turn(kind,text){const e=document.createElement('div');e.className='turn '+kind;e.dir='auto';e.textContent=(kind==='user'?'You: ':'Assistant: ')+text;chat.appendChild(e);return e}function assistant(text){const e=turn('assistant',text),b=document.createElement('button');b.className='audio';b.textContent='▶ Play audio';b.onclick=async()=>{b.disabled=true;try{const r=await fetch('/speak',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text})}),d=await r.json();if(!r.ok)throw Error(d.detail||'Audio failed.');new Audio('data:audio/wav;base64,'+d.audio).play()}catch(err){status.textContent=err.message}finally{b.disabled=false}};e.appendChild(document.createElement('br'));e.appendChild(b)}function codes(){return [...new Set(document.getElementById('codes').value.split(',').map(x=>x.trim()).filter(Boolean).concat(detectedCodes))].slice(0,6)}async function ask(message,showUser=true){if(showUser)turn('user',message);send.disabled=clear.disabled=true;status.textContent='Thinking…';try{const r=await fetch('/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message,history:history.slice(-10),glyph_codes:codes(),image_context:imageContext})}),d=await r.json();if(!r.ok)throw Error(d.detail||'Chat failed.');assistant(d.response);history.push({role:'user',content:message},{role:'assistant',content:d.response.slice(0,2000)});history.splice(0,Math.max(0,history.length-10));status.textContent=d.context_keys.length?'Local context: '+d.context_keys.join(', '):'No matching local description was supplied.'}catch(err){status.textContent=err.message}finally{send.disabled=clear.disabled=false}}document.getElementById('form').onsubmit=e=>{e.preventDefault();const box=document.getElementById('message'),message=box.value.trim();if(message){box.value='';ask(message)}};clear.onclick=()=>{history.length=0;detectedCodes=[];imageContext='';chat.replaceChildren();status.textContent='';imageInput.value=''};imageInput.onchange=async()=>{const file=imageInput.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){status.textContent='Use a JPG, PNG, or WebP image up to 10 MB.';return}const preview=turn('user','Uploaded image: '+file.name),img=document.createElement('img');img.className='image';img.src=URL.createObjectURL(file);preview.appendChild(document.createElement('br'));preview.appendChild(img);status.textContent='Detecting symbols…';send.disabled=clear.disabled=true;try{const form=new FormData();form.append('file',file);const r=await fetch('/detect',{method:'POST',body:form}),d=await r.json();if(!r.ok)throw Error(d.detail||'Detection failed.');const result=document.createElement('div');result.className='turn result';if(d.annotated_image){const annotated=document.createElement('img');annotated.className='image';annotated.src='data:image/jpeg;base64,'+d.annotated_image;result.textContent='Detection result:';result.appendChild(document.createElement('br'));result.appendChild(annotated)}if(!d.is_hieroglyph){result.append('\nNo hieroglyphs were found by image screening.')}else if(!d.detections.length){result.append('\nNo detector boxes were returned.')}else{detectedCodes=d.detections.map(x=>x.code);imageContext=d.detections.map(x=>x.label+': '+x.code+' (confidence '+x.confidence.toFixed(2)+(x.uncertain?', uncertain':'')+')').join('; ');const list=document.createElement('ul');list.className='symbols';d.detections.forEach(x=>{const li=document.createElement('li');li.textContent=x.label+' — '+x.code+' — '+Math.round(x.confidence*100)+'%'+(x.story?'':' — no local description')+(x.uncertain?' — uncertain':'');list.appendChild(li)});result.appendChild(list);result.append('These labels do not state reading order.');chat.appendChild(result);if(d.detections.length)await ask('Explain the detected symbols in this image. Use the Symbol labels when useful.',false)}d.warnings.forEach(w=>{const note=document.createElement('div');note.className='note';note.textContent=w;chat.appendChild(note)})}catch(err){status.textContent=err.message}finally{send.disabled=clear.disabled=false}};</script></html>"""
